# Hypothesis: for each 3x3 block, find all values that are not 0 and not 5.
# If any such value exists, output the MINIMUM of those values.
# Otherwise output 0.

def transform_hypothesis(grid):
    rows = len(grid)
    cols = len(grid[0])
    out_rows = rows // 3
    out_cols = cols // 3
    result = []
    for r in range(out_rows):
        row = []
        for c in range(out_cols):
            # Get all unique values in this 3x3 block
            values = set()
            for dr in range(3):
                for dc in range(3):
                    values.add(grid[r*3+dr][c*3+dc])
            # Find values that are not 0 and not 5
            special = values - {0, 5}
            if special:
                row.append(min(special))
            else:
                row.append(0)
        result.append(row)
    return result

